INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_FINN_ILMARINEN_KALEVA','ENT_FINN_ILMARINEN','SRC_KALEVALA','The Kalevala','The Kalevala','Take me to my distant country, I will send thee Ilmarinen, He will forge for thee the Sampo, Hammer thee the lid in colors, He may win thy lovely maiden; Worthy smith is Ilmarinen, In this art is first and master; He, the one that forged the heavens.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_ILMATAR_KALEVA','ENT_FINN_ILMATAR','SRC_KALEVALA','The Kalevala','Runo 1','Often we find him, in the runes, refusing to heed the call of his people for help, as when Ilmatar, the daughter of the air, vainly invoked him to her aid, that Wainamoinen, already seven hundred years unborn, might be delivered. So also Wainamoinen beseeches Ukko in vain to check the crimson streamlet flowing from his knee wounded by an axe in the hands of Hisi.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_KALMA_KALEVA','ENT_FINN_KALMA','SRC_KALEVALA','The Kalevala','The Kalevala','It would seem that the earliest beliefs of the Finns regarding the dead centred in this: that their spirits remained in their graves until after the complete disintegration of their bodies, over which Kalma, the god of the tombs, with his black and evil daughter, presided. After their spirits had been fully purified, they were then admitted to the Kingdom of Manala in the under world.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_KULLERVO_KALEVA','ENT_FINN_KULLERVO','SRC_KALEVALA','The Kalevala','The Kalevala','"The giants," says Grimm, "are distinguished by their cunning and ferocity from the stupid, good-natured monsters of Germany and Scandinavia." Soini, for example, a synonym of Kullervo, the hero of the saddest episode of the Kalevala when only three days old, tore his swaddling clothes to tatters.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_LEMMINKAINEN_KALEVA','ENT_FINN_LEMMINKAINEN','SRC_KALEVALA','The Kalevala','The Kalevala','"Yonder is thy golden infant, There thy holy babe lies sleeping, Hidden to his belt in water, Hidden in the reeds and rushes." Again when the devoted mother of the reckless hero, Lemminkainen, (chopped to pieces by the Sons Of Mana, as in the myth of Osiris) was raking together the fragments of his body from the river of Tuoni, and fearing that the sprites of the Death-stream might resent her intrusion, the Sun, in answer to h','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_LOUHI_KALEVA','ENT_FINN_LOUHI','SRC_KALEVALA','The Kalevala','Runos 5-8','Louhi steals Sun, Moon, and Fire RUNE XLVIII. Capture of the Fire-fish RUNE XLIX. Restoration of the Sun and Moon RUNE L. Mariatta-Wainamoinen''s Departure EPILOGUE GLOSSARY PREFACE The following translation was undertaken from a desire to lay before the English-speaking people the full treasury of epical beauty, folklore, and mythology comprised in _The Kalevala_, the national epic of the Finns.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_MIELIKKI_KALEVA','ENT_FINN_MIELIKKI','SRC_KALEVALA','The Kalevala','Runo 14:213','O Mielikki, forest-hostess, Tapio''s wife, thou fair Tellervo, Call thy dogs and well enchain them, Set in readiness thy hunters, Let them wait within their kennels. "Otso, thou O Forest-apple, Bear of honey-paws and fur-robes, Learn that Wainamoinen follows, That the singer comes to meet thee; Hide thy claws within thy mittens, Let thy teeth remain in darkness, That they may not harm the minstrel, May be powerless in battle.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_PANTHEON_KALEVA','ENT_FINN_PANTHEON','SRC_KALEVALA','The Kalevala','The Kalevala','"Every deity", says Castrén, "however petty he may be, rules in his own sphere as a substantial, independent power, or, to speak in the spirit of The Kalevala, as a self-ruling householder.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_POHJOLA_KALEVA','ENT_FINN_POHJOLA','SRC_KALEVALA','The Kalevala','The Kalevala','Lönnrot, and published in 1835 at Helsingfors, the quotation beginning with the 150th line of the 2nd Rune: Louhi Pohjolan emanta Sanan wirkko, noin nimesi: "Niin mita minulle annat, Kun saatan omille maille, Oman pellon pientarelle, Oman pihan rikkasille?" Sano wanha Wainamoinen: "Mitapa kysyt minulta, Kun saatat omille maille, Oman kaën kukkumille, Oman kukon kuuluwille, Oman saunan lampimille?" Sano Pohjolan emanta: "Ohoh w','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_TAPIO_KALEVA','ENT_FINN_TAPIO','SRC_KALEVALA','The Kalevala','Runos 14,','These deities are invariably described as gracious and tender-hearted, probably because they are all females with the exception of Tapio and his son, Nyrikki, a tall and stately youth who is engaged in building bridges over marshes and forest-streams, through which the herds must pass on their way to the woodland-pastures.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_TELLERVO_KALEVA','ENT_FINN_TELLERVO','SRC_KALEVALA','The Kalevala','The Kalevala','"Beauteous virgin of the woodlands, Tapio''s most charming daughter, Fair Tellervo, forest-maiden, Softly clad in silken raiment, Beautiful in golden ringlets, Do thou give my herds protection, In the Metsola dominions, On the hills of Tapiola; Shield them with thy hands of beauty, Stroke them gently with thy fingers, Give to them a golden lustre, Make them shine like fins of salmon, Grow them robes as soft as ermine.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_TUONELA_KALEVA','ENT_FINN_TUONELA','SRC_KALEVALA','The Kalevala','The Kalevala','Nasshut, blind and crippled shepherd, Wretched shepherd of Pohyola, Stood beside the death-land river, Near the sacred stream and whirlpool, Guarding Tuonela''s waters, Waiting there for Lemminkainen, Listening there for Kaukomieli, Waiting long the hero''s coming.','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_FINN_TUONETAR_KALEVA','ENT_FINN_TUONETAR','SRC_KALEVALA','The Kalevala','The Kalevala','Bring thy boat, Tuoni''s daughter, Tiny maiden of Manala, Come and row me o''er the ferry." Mana''s daughter does as bidden, Brings her boat to Wainamoinen, Quickly rows him through the channel, O''er the black and fatal river, To the kingdom of Manala, Speaks these words to the magician: "Woe to thee! O Wainamoinen! Wonderful indeed, thy magic, Since thou comest to Manala, Comest neither dead nor dying." Tuonetar, the death-land','John Martin Crawford',1888,'https://www.gutenberg.org/ebooks/5186',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact rune); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
